// #4572c6 (cd8e8bb3e10ac268a44572c6 «שלח קוד מחדש» מציג «נשלח קוד חדש» אבל המסרון לא מגיע) + #41747e (6a86f7feb882fcc40241747e, F-39 AC3/AC4)
// — עבר QA 03.11.2026 пользователем (Android Pixel 6, app 1.0.0 (6) + OTA, SMS Pulseem).
// מה רצוי: #4572c6 по F-39 AC2 — «נשלח קוד חדש» только когда SMS реально отправлено, иначе — понятное сообщение на иврите;
// F-39 AC3 «קוד ישן מפסיק להיות תקף כאשר נשלח קוד חדש»; F-39 AC4 / F-88 AC5 — повторная отправка доступна.
// Факт 03.11 (session-2026-11-03.json, otp-0311-android-03, -07..-10): resend → «נשלח קוד חדש. הזינו את שש הספרות החדשות.», SMS пришло
// (в т.ч. два resend с интервалом 23 с — SMS4 и SMS5); код SMS4 после SMS5 → «הקוד שהוזן אינו נכון…»; код SMS5 → вход, главная.
//
// Q-22a — авто: 2 платных SMS (вход + resend) → QA_SMS=1 + QA_OTP_PHONE. @data: выходит из аккаунта.
// Q-22b — @manual-otp (QA_OTP_MANUAL=1): ЧЕЛОВЕК вводит код из ПРЕДПОСЛЕДНЕГО SMS → тест ждёт «אינו נכון» (AC3);
//          затем код из ПОСЛЕДНЕГО SMS → тест ждёт главный экран (SMS после resend реально пришло — #4572c6).
// Пришло ли SMS — видит только человек (на номер QA_OTP_PHONE). Resend через 23 с и «баланс Pulseem 0 → «לא נשלח קוד חדש…»» — вручную.
// Кейс: .qa/tests/auth-login/AL-07-otp-resend-old-code.md. Файл serial: Q-22b продолжает экран Q-22a.
import { expect } from '@wdio/globals';
import { byText, byTextContains } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn } from '../../helpers/app.ts';
import {
  requireSms, requireManualOtp, toPhoneScreen, submitPhone, waitCodeScreen, expectHebrewMessage, expectNoTestMode, waitHumanFor,
  OTP_PHONE, SENT_TO, RESEND, RESENT, RESEND_FAILED_PREFIX, WRONG_CODE, EXPIRED_CODE, MANUAL_WAIT,
} from '../_lib/app-0311.ts';

describe('03.11 — «שלח קוד מחדש»: новое SMS, старый код не принимается (#4572c6 #41747e)', function () {
  before(async function () { requireSms(this); });
  after(async function () {
    this.timeout(60000);
    if (!(await isLoggedIn())) {
      await ensureAppReady().catch((e) => console.log(`[Q-22] вход USER1 не восстановлен (${(e as Error).message}) — войти вручную`));
    }
  });

  it('Q-22a Экран кода → «שלח קוד מחדש» → «נשלח קוד חדש. הזינו את שש הספרות החדשות.», нет «לא נשלח קוד חדש», остаёмся на экране кода с номером, кнопка снова доступна #4572c6 #41747e @android @data @sms', async function () {
    this.timeout(180000);
    await toPhoneScreen();
    await submitPhone(OTP_PHONE);
    await waitCodeScreen();
    await expect(byText(SENT_TO(OTP_PHONE))).toBeDisplayed({ wait: 10000 });

    const resend = await byText(RESEND);
    await expect(resend).toBeDisplayed();
    await resend.click();
    await expectHebrewMessage('נשלח קוד חדש');
    await expect(byText(RESENT)).toBeDisplayed();
    await expect(byTextContains(RESEND_FAILED_PREFIX)).not.toBeExisting();   // ложного успеха нет и ошибки нет (баланс пополнен 03.11)
    await expect(byText(SENT_TO(OTP_PHONE))).toBeDisplayed();
    await expectNoTestMode();
    await expect(byText(RESEND)).toBeDisplayed({ wait: 30000 });           // F-39 AC4: повторная отправка остаётся
  });

  it('Q-22b @manual-otp Человек: код из ПРЕДПОСЛЕДНЕГО SMS → «הקוד שהוזן אינו נכון…» (не вход, не «פג תוקף»); код из ПОСЛЕДНЕГО SMS → главная #41747e #4572c6 @android @data @sms @manual-otp', async function () {
    requireManualOtp(this);
    this.timeout(2 * MANUAL_WAIT + 60000);
    await waitCodeScreen(10000);

    // F-39 AC3: старый код после resend отклоняется.
    const r1 = await waitHumanFor(`на ${OTP_PHONE} пришло 2 SMS — введите код из ПЕРВОГО (старого) и нажмите «שלח»`,
      ['הקוד שהוזן אינו נכון', '__HOME__', 'הקוד פג תוקף']);
    expect(r1).toBe('הקוד שהוזן אינו נכון');       // '__HOME__' = старый код принят — нарушение F-39 AC3
    await expect(byText(WRONG_CODE)).toBeDisplayed();
    await expect(byTextContains(EXPIRED_CODE)).not.toBeExisting();

    // #4572c6: SMS после resend реально пришло — его код входит.
    const r2 = await waitHumanFor('теперь введите код из ПОСЛЕДНЕГО SMS (после «שלח קוד מחדש») и нажмите «שלח»', ['__HOME__']);
    expect(r2).toBe('__HOME__');
    await expect(byText('בית')).toBeDisplayed();
  });
});
